<?php declare(strict_types=1);$reportOperation=$reportUi['operation'];$reportBlocked=$reportUi['blocked'];$reportIsRegenerate=$reportOperation['action']==='activity-report-regenerate';?>
<section class="card" data-activity-report-operation><h2><?=e($reportText('Berichtsaktion'))?></h2><p><?=e($reportText($reportBlocked?'Die Aktion wurde nicht bestätigt. Vergleiche sie mit dem gespeicherten Bericht, bevor du fortfährst.':'Bitte die Berichtsaktion prüfen und erneut bestätigen.'))?></p><a class="btn btn-outline theme-secondary" href="<?=e($reportUrl(['report_id'=>$reportOperation['id']]))?>"><?=e($reportText('Gespeicherten Bericht öffnen'))?></a>
<?php try{$reportCurrentComparison=$reports->get($reportOperation['id']);}catch(\DomainException){$reportCurrentComparison=null;}if($reportCurrentComparison!==null):?><details data-activity-report-current-comparison><summary><?=e($reportText('Aktuell gespeicherten Bericht vergleichen'))?></summary><article class="report-body"><?=nl2br(e($reportCurrentComparison['body']))?></article></details><?php endif?>
<fieldset <?=$reportBlocked?'disabled':''?>><form method="post" action="<?=e($reportUrl(['report_id'=>$reportOperation['id']]))?>" data-activity-report-original-operation <?=$reportBlocked?'data-activity-report-readonly':''?>><?=csrf().hidden('report_kind',$reportKind).hidden('report_id',$reportOperation['id']).hidden('version',$_POST['version']).hidden('source_hash',$reportOperation['source_hash'])?>
<?php if($reportIsRegenerate):?><?=hidden('action','activity-report-regenerate')?><label class="check"><input class="check" type="checkbox" name="confirm_report" value="1" required <?=$reportOperation['confirmed']?'checked':''?>><span><?=e($reportText('Ich möchte den gespeicherten Berichtstext durch die ermittelten Tätigkeiten ersetzen.'))?></span></label><button class="btn btn-outline theme-secondary"><?=e($reportText('Berichtstext durch diese Fassung ersetzen'))?></button>
<?php else:?><?=hidden('preview_token',$reportOperation['preview_token'])?><?php if($reportUi['is_chair']):?><label class="check"><input class="check" type="checkbox" name="with_signature" value="1" <?=$reportOperation['with_signature']?'checked':''?>><span><?=e($reportText('Meine hinterlegte Unterschrift für genau diesen Bericht verwenden.'))?></span></label><?php endif?><button class="btn btn-outline theme-secondary" name="action" value="activity-report-preview" formtarget="activity-report-preview-<?=e($reportOperation['id'])?>" formnovalidate><?=e($reportText('Gespeicherten Bericht als PDF ansehen'))?></button><details class="report-pdf-preview" open><summary><?=e($reportText('PDF-Vorschau'))?></summary><p><?=e($reportText('Mit „Gespeicherten Bericht als PDF ansehen“ erscheint das vollständige PDF hier. Danach kannst du direkt darunter die Freigabe bestätigen.'))?></p><iframe name="activity-report-preview-<?=e($reportOperation['id'])?>" title="<?=e($reportText('PDF-Vorschau des Tätigkeitsberichts'))?>" data-activity-report-pdf-frame srcdoc="<?=e('<p>'.e($reportText('Noch keine PDF-Vorschau geöffnet.')).'</p>')?>"></iframe></details><?php if($reportUi['is_chair']):?><label class="check"><input class="check" type="checkbox" name="reviewed" value="1" required <?=$reportOperation['reviewed']?'checked':''?>><span><?=e($reportText('Ich habe das vollständige PDF geprüft und gebe diese Fassung frei.'))?></span></label><button class="btn btn-solid theme-primary" name="action" value="activity-report-approve"><?=e($reportText('Bericht freigeben'))?></button><?php endif?><?php endif?></form></fieldset></section>
